export function createClient(){window.__providerCounts.clients++;return{auth:{getUser:async()=>{window.__providerCounts.users++;return{data:{user:window.__identity.anonymous?null:{id:window.__identity.actorId}},error:null};},getClaims:async()=>{window.__providerCounts.claims++;return{data:{claims:window.__identity.anonymous?null:{sub:window.__identity.actorId,session_id:window.__identity.sessionId,iss:'https://nnhcnvksxgxnpvdqjgpg.supabase.co/auth/v1',exp:Math.floor(Date.now()/1000)+3600}},error:null};},onAuthStateChange:callback=>{window.__authListeners.add(callback);return{data:{subscription:{unsubscribe:()=>window.__authListeners.delete(callback)}}};}},rpc:async(name)=>{if(name!=='get_tournament_role')throw Error('Unapproved fictional RPC');window.__providerCounts.roles++;return{data:window.__identity.role,error:null};}};}
